exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  02 · memoize the task                                       ★★☆ core
//  concepts: task caching · stampede prevention
// ─────────────────────────────────────────────────────────────────────────
//
//  Ten requests arrive while the first load is still running. Caching the
//  RESULT means ten loads. Cache the in-flight TASK and they all share one.

using static Bootcamp.Check;

Func<Task<string>> Once(Func<Task<string>> factory)
{
    Task<string>? cached = null;
    return () => cached ??= factory();
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("two calls before completion return the very same Task", () =>
{
    var tcs = new TaskCompletionSource<string>();
    var f = Once(() => tcs.Task);
    var t1 = f();
    var t2 = f();
    Ok(ReferenceEquals(t1, t2), "both callers must share one in-flight Task");
});

Test("the factory runs once while the load is still in flight (boundary)", () =>
{
    var tcs = new TaskCompletionSource<string>();
    int calls = 0;
    var f = Once(() => { calls++; return tcs.Task; });
    var t1 = f();
    var t2 = f();
    Ok(!t1.IsCompleted, "nothing has completed yet");
    Eq(calls, 1);
});

Test("completing the source completes every caller with its value", async () =>
{
    var tcs = new TaskCompletionSource<string>();
    var f = Once(() => tcs.Task);
    var t1 = f();
    var t2 = f();
    tcs.SetResult("v");
    Eq(await t1, "v");
    Eq(await t2, "v");
});

Test("a call after completion still reuses the first load", async () =>
{
    var tcs = new TaskCompletionSource<string>();
    int calls = 0;
    var f = Once(() => { calls++; return tcs.Task; });
    f();
    tcs.SetResult("v");
    var t3 = f();
    Eq(await t3, "v");
    Eq(calls, 1);
});

