exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  03 · whenany first wins                                     ★★☆ core
//  concepts: WhenAny · hedged reads
// ─────────────────────────────────────────────────────────────────────────
//
//  Two replicas are asked the same question; serve whichever answers
//  first. WhenAny tells you WHICH task finished — not its value.

using static Bootcamp.Check;

async Task<string> FirstReadyAsync(Task<string> a, Task<string> b)
{
    var first = await Task.WhenAny(a, b);
    if (first.IsCompletedSuccessfully) return first.Result;
    var other = first == a ? b : a;
    return await other;   // its value, or its exception when both replicas failed
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("a already done, b pending -> a's value", async () =>
{
    var pending = new TaskCompletionSource<string>();
    Eq(await FirstReadyAsync(Task.FromResult("a"), pending.Task), "a");
});

Test("b completes first -> \"b\"", async () =>
{
    var a = new TaskCompletionSource<string>();
    var b = new TaskCompletionSource<string>();
    var first = FirstReadyAsync(a.Task, b.Task);
    b.SetResult("b");
    a.SetResult("a");
    Eq(await first, "b");
});

Test("a completes first -> \"a\"", async () =>
{
    var a = new TaskCompletionSource<string>();
    var b = new TaskCompletionSource<string>();
    var first = FirstReadyAsync(a.Task, b.Task);
    a.SetResult("a");
    b.SetResult("b");
    Eq(await first, "a");
});

Test("both already done -> the first argument wins (boundary)", async () =>
    Eq(await FirstReadyAsync(Task.FromResult("a"), Task.FromResult("b")), "a"));

Test("a replica that FAILS first does not win: the other one's value is served (boundary)", async () =>
{
    var a = new TaskCompletionSource<string>();
    var b = new TaskCompletionSource<string>();
    var first = FirstReadyAsync(a.Task, b.Task);
    a.SetException(new InvalidOperationException("replica a is down"));
    b.SetResult("b");
    Eq(await first, "b");
});

Test("when both replicas fail, the failure surfaces", async () =>
{
    var a = new TaskCompletionSource<string>();
    var b = new TaskCompletionSource<string>();
    var first = FirstReadyAsync(a.Task, b.Task);
    a.SetException(new InvalidOperationException("replica a is down"));
    b.SetException(new InvalidOperationException("replica b is down"));
    await ThrowsAsync<InvalidOperationException>(async () => await first, "is down");
});

