exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  04 · sync throw vs faulted                                  ★★★ stretch
//  concepts: eager validation · async local functions
// ─────────────────────────────────────────────────────────────────────────
//
//  Bad arguments should explode at the call site, not inside a Task that
//  someone may never await. An async method can't do that — split it.

using System.Globalization;
using static Bootcamp.Check;

Task<int> ParseAndLoadAsync(string id, Func<int, Task<int>> load)
{
    if (!int.TryParse(id, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed))
        throw new ArgumentException($"id '{id}' is not a number", nameof(id));
    return LoadCore(parsed);

    async Task<int> LoadCore(int value) => await load(value);
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("a non-numeric id throws synchronously, before any Task exists (boundary)", () =>
    Throws<ArgumentException>(() => { _ = ParseAndLoadAsync("abc", n => Task.FromResult(0)); }));

Test("\"7\" loads 70", async () =>
    Eq(await ParseAndLoadAsync("7", n => Task.FromResult(n * 10)), 70));

Test("\"0\" is a valid id (boundary)", async () =>
    Eq(await ParseAndLoadAsync("0", n => Task.FromResult(n + 1)), 1));

Test("a bad id never reaches the loader", () =>
{
    int loads = 0;
    Throws<ArgumentException>(() => { _ = ParseAndLoadAsync("x1", n => { loads++; return Task.FromResult(n); }); });
    Eq(loads, 0);
});

