{
    // TODO: await each fetch before starting the next; results in input order
    throw new NotImplementedException();
}

exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  05 · sequential pipeline                                    ★★☆ core
//  concepts: ordered awaits · sequential pipelines
// ─────────────────────────────────────────────────────────────────────────
//
//  The downstream API allows one request at a time (rate limits, or each
//  call depends on the previous one). Await each fetch before the next.

using static Bootcamp.Check;

async Task<List<int>> LoadAllAsync(List<int> ids, Func<int, Task<int>> fetch)
{
    var results = new List<int>();
    foreach (var id in ids)
        results.Add(await fetch(id));
    return results;
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("[1,2,3] -> [2,4,6] in input order", async () =>
    Eq(await LoadAllAsync([1, 2, 3], id => Task.FromResult(id * 2)), new[] { 2, 4, 6 }));

Test("fetch is called in input order", async () =>
{
    var calls = new List<int>();
    await LoadAllAsync([1, 2, 3], id => { calls.Add(id); return Task.FromResult(id * 2); });
    Eq(calls, new[] { 1, 2, 3 });
});

Test("no ids -> [] and zero calls (boundary)", async () =>
{
    int calls = 0;
    var got = await LoadAllAsync([], id => { calls++; return Task.FromResult(id); });
    Eq(got, Array.Empty<int>());
    Eq(calls, 0);
});

Test("a single id -> one result", async () =>
    Eq(await LoadAllAsync([21], id => Task.FromResult(id * 2)), new[] { 42 }));

Test("the next fetch does not start until the previous one finished", async () =>
{
    var gates = new List<TaskCompletionSource<int>>();
    var all = LoadAllAsync([1, 2], id => { var g = new TaskCompletionSource<int>(); gates.Add(g); return g.Task; });
    if (all.IsFaulted) await all;
    Eq(gates.Count, 1, "only the first fetch may be in flight");
    gates[0].SetResult(10);
    Eq(gates.Count, 2, "finishing the first fetch starts the second");
    gates[1].SetResult(20);
    Eq(await all, new[] { 10, 20 });
});

