exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  06 · tcs bridge                                             ★★☆ core
//  concepts: TaskCompletionSource · callback bridging
// ─────────────────────────────────────────────────────────────────────────
//
//  An old SDK pushes messages through a callback. Your code wants
//  `await NextMessageAsync(...)`. TaskCompletionSource is the adapter.

using static Bootcamp.Check;

Task<string> NextMessageAsync(Action<Action<string>> subscribe)
{
    var tcs = new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);
    subscribe(msg => tcs.TrySetResult(msg));
    return tcs.Task;
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("nothing fired yet -> the task is still pending (boundary)", () =>
{
    Action<string>? handler = null;
    var next = NextMessageAsync(cb => handler = cb);
    Ok(handler is not null, "subscribe must receive a handler");
    Ok(!next.IsCompleted, "no message has arrived yet");
});

Test("firing the handler completes the task with the message", async () =>
{
    Action<string>? handler = null;
    var next = NextMessageAsync(cb => handler = cb);
    handler!("hi");
    Eq(await next, "hi");
});

Test("a second event keeps the first value", async () =>
{
    Action<string>? handler = null;
    var next = NextMessageAsync(cb => handler = cb);
    handler!("first");
    handler!("second");
    Eq(await next, "first");
});

Test("subscribe is invoked exactly once", () =>
{
    int subscriptions = 0;
    NextMessageAsync(cb => subscriptions++);
    Eq(subscriptions, 1);
});

