//  expected failure into a soft result and let everything else stay loud.

using static Bootcamp.Check;

async Task<(bool Ok, string Value, string Error)> TryLoadAsync(Func<Task<string>> load)
{
    // TODO: success -> (true, value, ""); InvalidOperationException -> (false, "", message); anything else propagates
    throw new NotImplementedException();
}

exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  07 · try load funnel                                        ★★☆ core
//  concepts: expected vs unexpected failure · selective catch
// ─────────────────────────────────────────────────────────────────────────
//
//  "Not found" is an outcome; a NullReferenceException is a bug. Turn the
//  expected failure into a soft result and let everything else stay loud.

using static Bootcamp.Check;

async Task<(bool Ok, string Value, string Error)> TryLoadAsync(Func<Task<string>> load)
{
    try
    {
        return (true, await load(), "");
    }
    catch (InvalidOperationException ex)
    {
        return (false, "", ex.Message);
    }
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("success -> (true, value, \"\")", async () =>
    Eq(await TryLoadAsync(() => Task.FromResult("data")), (true, "data", "")));

Test("an InvalidOperationException becomes (false, \"\", message)", async () =>
    Eq(await TryLoadAsync(() => throw new InvalidOperationException("boom")), (false, "", "boom")));

Test("an unexpected exception type escapes", async () =>
    await ThrowsAsync<ArgumentException>(async () => await TryLoadAsync(() => throw new ArgumentException("bad")), "bad"));

Test("an empty value is still a success (boundary)", async () =>
    Eq(await TryLoadAsync(() => Task.FromResult("")), (true, "", "")));

