exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  08 · task status snapshot                                   ★☆☆ warm-up
//  concepts: TaskStatus flags · terminal states
// ─────────────────────────────────────────────────────────────────────────
//
//  A health endpoint reports on a background warm-up Task. A Task can end
//  three ways — and plain IsCompleted is true for all three.

using static Bootcamp.Check;

string Describe(Task t)
{
    if (t.IsCompletedSuccessfully) return "ok";
    if (t.IsFaulted) return "failed";
    if (t.IsCanceled) return "canceled";
    return "pending";
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("a completed task -> ok", () =>
    Eq(Describe(Task.CompletedTask), "ok"));

Test("a faulted task -> failed", () =>
    Eq(Describe(Task.FromException(new InvalidOperationException("x"))), "failed"));

Test("a canceled task -> canceled", () =>
    Eq(Describe(Task.FromCanceled(new CancellationToken(true))), "canceled"));

Test("a never-completed task -> pending (boundary)", () =>
    Eq(Describe(new TaskCompletionSource<int>().Task), "pending"));
